using Arrhenius, NPZ, LinearAlgebra, Printf
np=266; ref=NPZ.npzread(joinpath(@__DIR__,"..","data","cantera_h2o2_two_point_$(np)pt.npz")); gas=CreateSolution(joinpath(dirname(pathof(Arrhenius)),"..","mechanism","h2o2.yaml")); z=vec(Float64.(ref["grid"]))
f=CounterflowDiffusionFlame(gas;fuel="H2:1",oxidizer="O2:1",mdot_fuel=only(ref["turning_fuel_mdot"]),mdot_oxidizer=only(ref["turning_oxidizer_mdot"]),T_fuel=300.,T_oxidizer=500.,P=only(ref["pressure_Pa"]),width=.018,grid=z)
T=vec(Float64.(ref["T"])); Y=Matrix{Float64}(ref["Y"]); V=vec(Float64.(ref["spreadRate"])); L=vec(Float64.(ref["Lambda"])); vel=vec(Float64.(ref["velocity"])); rho=only(ref["pressure_Pa"])./(Y*(1 ./gas.MW))./(Arrhenius.R.*T); u=zeros(gas.n_species+4,length(z)); u[1,:]=T./1000; u[2:gas.n_species+1,:]=permutedims(Y); u[gas.n_species+2,:]=V./Arrhenius._counterflow_Vscale; u[gas.n_species+3,:]=L./Arrhenius._counterflow_Lscale; u[end,:]=rho.*vel; f.state=u; f.converged=true
w=CounterflowWorkspace(f); r=similar(u); counterflow_residual!(r,f,u,w); Arrhenius._counterflow_jacobian!(f,u,w,r;analytic=true); weights=[max(.05*maximum(abs,@view(u[k,:])),1e-7) for k in axes(u,1)]; Arrhenius._continuation_tangent!(f,w,u,f.fuel_mass_flux,:fuel_mass_flux,weights,max(abs(f.fuel_mass_flux),1.);analytic=true)
@printf("warm N=%d residual_s=%.6f jacobian_s=%.6f tangent_s=%.6f\n",length(z),@elapsed(counterflow_residual!(r,f,u,w)),@elapsed(Arrhenius._counterflow_jacobian!(f,u,w,r;analytic=true)),@elapsed(Arrhenius._continuation_tangent!(f,w,u,f.fuel_mass_flux,:fuel_mass_flux,weights,max(abs(f.fuel_mass_flux),1.);analytic=true))); flush(stdout)
